// Group new high-intent roles by company domain and deduplicate seen job IDs
const staticData = $getWorkflowStaticData('global');
staticData.seenJobUrls = staticData.seenJobUrls || [];
const seen = new Set(staticData.seenJobUrls);

const domainMap = { anthropic: 'anthropic.com', linear: 'linear.app', palantir: 'palantir.com' };
const summaryByDomain = {};
const newlySeen = [];

for (const item of $input.all()) {
  const job = item.json;
  if (!job.b2bBuyingSignals || job.b2bBuyingSignals.length === 0) continue;
  if (job.applyUrl && seen.has(job.applyUrl)) continue;
  if (job.applyUrl) newlySeen.push(job.applyUrl);

  const dom = (job.companyDomain || domainMap[job.companySlug] || (job.companySlug + '.com')).toLowerCase();
  if (!summaryByDomain[dom]) {
    summaryByDomain[dom] = { domain: dom, rolesCount: 0, maxSalaryUsd: 0, sampleRoleTitle: job.title, sampleApplyUrl: job.applyUrl || '', signals: new Set() };
  }
  summaryByDomain[dom].rolesCount += 1;
  const salMax = job.compensation?.maxUsd || job.compensation?.minUsd || 0;
  if (salMax > summaryByDomain[dom].maxSalaryUsd) {
    summaryByDomain[dom].maxSalaryUsd = salMax;
    summaryByDomain[dom].sampleRoleTitle = job.title;
    summaryByDomain[dom].sampleApplyUrl = job.applyUrl || '';
  }
  job.b2bBuyingSignals.forEach(s => summaryByDomain[dom].signals.add(s));
}

staticData.seenJobUrls = [...staticData.seenJobUrls, ...newlySeen].slice(-1000);
const accounts = Object.values(summaryByDomain).map(a => ({ ...a, signals: Array.from(a.signals) }));

return [{ json: { domains: accounts.map(a => a.domain), accountSummaries: accounts } }];

// Join hiring signal counts + salary budgets with verified MX executive contacts
const accounts = $('3. Group Signals & Deduplicate Jobs').item.json.accountSummaries || [];
const byDomain = Object.fromEntries(accounts.map(a => [a.domain, a]));

return $input.all()
  .map(i => i.json)
  .filter(c => c && c.domain && c.mxVerification?.hasValidMx)
  .map(c => {
    const dom = c.domain.toLowerCase();
    const sig = byDomain[dom] || {};
    const execs = (c.likelyExecutiveEmails || []).slice(0, 3).map(e => e.email);
    const directs = (c.directEmails || []).map(e => e.email);
    return {
      json: {
        domain: dom,
        companyName: c.companyName || dom,
        rolesCount: sig.rolesCount || 0,
        maxSalaryUsd: sig.maxSalaryUsd || 0,
        sampleRoleTitle: sig.sampleRoleTitle || '',
        sampleApplyUrl: sig.sampleApplyUrl || '',
        buyingSignals: (sig.signals || []).join(', '),
        mailProvider: c.mxVerification.mailProvider,
        bestContactEmail: directs[0] || execs[0] || '',
        executiveCandidates: execs.join(', '),
        linkedinUrls: (c.socialProfiles?.linkedin || []).join(', ')
      }
    };
  });
